function activeTask(){return state.tasks.find(t=>['queued','running','timeout','cancelling'].includes(t.status))}
function statusText(s){return {queued:'排队中',running:'生成中',timeout:'等待超时',cancelling:'取消处理中',cancelled:'已取消',failed:'已失败',done:'已完成'}[s]||s}
