function addMessage(role,text,extra={}){state.messages.push({id:Date.now()+Math.random(),role,text,...extra})}
function scrollFeed(){requestAnimationFrame(()=>{const f=$('.agent-feed');if(f)f.scrollTo({top:f.scrollHeight,behavior:'instant'})})}
function recommendedRefs(ids){if(ids.length<=6)return [...ids];const pick=[];for(const [group,count] of [['product',2],['model',1],['reference',2],['brand',1]]){pick.push(...ids.filter(id=>asset(id)?.group===group).slice(0,count))}for(const id of ids)if(pick.length<6&&!pick.includes(id))pick.push(id);return pick.slice(0,6)}
